/* Public field guide. Generated rule data comes from the current game checkout. */
window.GuardiansFieldGuide = function(ctx) {
  'use strict';
  const {L,PAGES,TR_HEAD,NAV,PLACES,DTR}=ctx, D=window.GuardiansCurrentData;
  const E=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const U=(id,anchor='')=>L('/','/es/')+id+'/'+(anchor?'#'+anchor:'');
  const A=(id,en,es,anchor='')=>`<a class="ed-link" href="${U(id,anchor)}">${L(en,es)} ↗</a>`;
  const P=(en,es)=>`<p class="b">${L(en,es)}</p>`;
  const H=(en,es)=>`<h2 class="s">${L(en,es)}</h2>`;
  const N=(en,es)=>`<aside class="callout">${P(en,es)}</aside>`;
  const stamp=(preview=false)=>`<p class="fg-reviewed"><time datetime="${D.reviewed}">${L('Reviewed November 9, 2026','Revisado el 9 de noviembre de 2026')}</time><span>${preview?L('Preview · not a launch announcement','Avance · no anuncia una apertura'):L('Player reference · check the game for availability','Guía del jugador · consulta la disponibilidad en el juego')}</span></p>`;
  const table=(headers,rows)=>`<div class="tw"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const img=(name,alt,cls='')=>`<img class="${cls}" src="/assets/updates-20261109/${name}.webp" alt="${E(alt)}" loading="lazy">`;
  const append=(id,fn)=>{const old=PAGES[id].h;PAGES[id].h=()=>old()+fn();};
  const prepend=(id,fn)=>{const old=PAGES[id].h;PAGES[id].h=()=>fn()+old();};
  const number=n=>Number(n).toLocaleString(L('en-US','es-AR'));
  const steps=rows=>`<ol class="fg-turns">${rows.map(([en,es],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div>${L(en,es)}</div></li>`).join('')}</ol>`;
  const regionName=id=>D.territories[id]?.name||({harrowmere:'Harrowmere',sunken_fang_archipelago:'Sunken Fang Archipelago',hollowstar_crater:'Hollowstar Crater',nyxhaven:'Nyxhaven'}[id])||id;

  function support(id="combat-teamplay"){return `<section id="${id}" class="fg-section">${H('One main action. A separate support choice.','Una acción principal. Una decisión de apoyo adicional.')}${stamp()}
    ${P('Choose <strong>Attack, Parry, Rest or a weapon active</strong> as your main action. If you use a consumable, confirm its target as well. Using a potion does not submit your main action. The item is spent when its effect resolves.','Elige <strong>Attack, Parry, Rest o una activa de arma</strong> como acción principal. Si usas un consumible, confirma también su objetivo. Usar una poción no completa tu acción principal. El objeto se gasta cuando se resuelve su efecto.')}
    ${table(L(['Effect','Who can receive it?','Remember'],['Efecto','¿Quién puede recibirlo?','Recuerda']),[
      ['Health / Ultra Health / Mega Health',L('You or a living ally','Tú o un aliado vivo'),L('50 / 100 / 150 HP, limited by missing HP.','50 / 100 / 150 HP, hasta el HP que le falte.')],
      ['Critical, Guard, Power, Focus, Regen, Buried Titan, Last Stand, Protective Shield, Void Aegis',L('You or a living ally','Tú o un aliado vivo'),L('Check the chosen recipient. Focus Potion prepares next-round Focus; it does not create Ultra Focus.','Comprueba el destinatario elegido. Focus Potion prepara Focus para la siguiente ronda; no crea Ultra Focus.')],
      ['Resurrection Potion',L('A fallen ally','Un aliado caído'),L('Revival is a separate effect; ordinary healing cannot revive.','Revivir es un efecto distinto; una cura normal no revive.')],
      ['Mind Cleanser',L('An enemy','Un enemigo'),L('Removes cleanseable Focus, including queued Focus and Ultra Focus.','Elimina Focus limpiable, incluido el pendiente y Ultra Focus.')],
      [L('Group healing','Curas de grupo'),L('Recipients selected by the effect','Destinatarios definidos por el efecto'),L('Tidal Mending and Warden’s Pact follow their own targeting rules.','Tidal Mending y Warden’s Pact siguen sus propias reglas de selección.')],
      ['Scorched Will',L('The wearer, automatically','El portador, automáticamente'),L('Ashen Hunt exclusive: below 30% HP, once per fight. It cannot save a wearer already at 0 HP.','Exclusivo de Ashen Hunt: por debajo del 30% de HP, una vez por combate. No salva a un portador que ya quedó en 0 HP.')]
    ])}
    ${N('<strong>Alchemist: choose one auxiliary use per round.</strong> A dose, your equipped consumable or First Aid Kit. You cannot combine all three. Doses do not spend inventory and do not receive Quartermaster’s consumable amplification.','<strong>Alquimista: elige un uso auxiliar por ronda.</strong> Una dosis, tu consumible equipado o First Aid Kit. No puedes combinar los tres. Las dosis no gastan inventario ni reciben la amplificación de consumibles de Quartermaster.')}
    ${A('mastery','Read every character’s rules','Consulta las reglas de cada personaje')}
  </section>`;}
  function examples(){return `<section id="combat-worked-turns" class="fg-section">${H('Three short battles to understand your choices','Tres combates breves para entender tus decisiones')}${P('These examples assume the stated actions succeed. They illustrate timing and resource use; enemy decisions, shields and mode effects can change a real fight.','Estos ejemplos suponen que se cumplen las condiciones indicadas. Explican tiempos y recursos; las decisiones enemigas, los escudos y los efectos del modo pueden cambiar una pelea real.')}
    <details class="fg-example" open><summary>${L('01 · Lancer: build, then spend','01 · Lancero: acumular y después gastar')}</summary>${steps([
      ['<strong>Round 1:</strong> at stage 1, hit an enemy before their turn. Gain 1 Anticipation charge. This hit has no prepared bonus.','<strong>Ronda 1:</strong> en etapa 1, acierta antes del turno enemigo. Obtienes 1 carga de Anticipación. Ese golpe aún no recibe el bono preparado.'],
      ['<strong>Round 2:</strong> hit before the enemy again. Reach 2 charges. The charge you just earned prepares a later attack.','<strong>Ronda 2:</strong> vuelve a acertar antes del rival. Llegas a 2 cargas. La carga que acabas de ganar prepara un ataque posterior.'],
      ['<strong>Round 3:</strong> your next basic attack spends both for +10% damage, even if this enemy acts first. That prepared attack does not build another charge.','<strong>Ronda 3:</strong> tu siguiente ataque básico gasta ambas para añadir 10% de daño, aunque ahora el rival actúe primero. Ese ataque preparado no genera otra carga.']
    ])}${P('Weapon attacks join this mechanic from stage 4. Earlier stages do not turn every weapon skill into a prepared thrust.','Los ataques principales de habilidades de arma participan desde la etapa 4. Las etapas anteriores no convierten cualquier habilidad en una estocada preparada.')}</details>
    <details class="fg-example"><summary>${L('02 · Alchemist: help without losing your action','02 · Alquimista: ayudar sin perder tu acción')}</summary>${steps([
      ['<strong>Round 1:</strong> choose Rest safely. If it succeeds, stage 1 creates one dose for use from the next round. Interrupted Rest creates none.','<strong>Ronda 1:</strong> elige Rest cuando puedas completarlo. Si tiene éxito, la etapa 1 crea una dosis utilizable desde la ronda siguiente. Un Rest interrumpido no crea ninguna.'],
      ['<strong>Round 2:</strong> an ally has 80/200 HP. In the Class panel, prepare your 40 HP dose for them; also choose your main action, such as Parry. The dose can bring them to 120/200.','<strong>Ronda 2:</strong> un aliado tiene 80/200 HP. En el panel de Clase, prepara tu dosis de 40 HP para él; elige además tu acción principal, por ejemplo Parry. La dosis puede dejarlo en 120/200.'],
      ['<strong>Round 3:</strong> decide whether another safe Rest is useful. At stage 1 you can create only 2 doses per fight and store 1. A consumed dose is not an unlimited refill.','<strong>Ronda 3:</strong> decide si conviene otro Rest seguro. En etapa 1 solo puedes crear 2 dosis por combate y guardar 1. Gastar una dosis no habilita recargas ilimitadas.']
    ])}${P('At stage 5, Shared splits 60 healing into 30 + 30. It does not heal both recipients for 60. The mastery card explains stage 6’s larger pool and 75/25 option.','En etapa 5, Compartida reparte 60 de cura como 30 + 30. No cura 60 a cada destinatario. La ficha de maestría explica la reserva mayor y el reparto 75/25 de la etapa 6.')}</details>
    <details class="fg-example"><summary>${L('03 · Vareth: read the warning and coordinate','03 · Vareth: leer el aviso y coordinarse')}</summary>${steps([
      ['<strong>Round 1:</strong> prepare your equipment and preserve enough recovery for the group. A raid needs three Guardians, each confirming their own action.','<strong>Ronda 1:</strong> prepara tu equipo y conserva recuperación para el grupo. Una raid necesita tres Guardianes, cada uno confirmando su propia acción.'],
      ['<strong>Round 2, base cycle:</strong> Vareth announces his breath and marks the living Guardian with the most current HP. Each different Guardian who removes boss HP with Attack reduces the charge bonus by 20 percentage points.','<strong>Ronda 2, ciclo base:</strong> Vareth anuncia el aliento y marca al Guardián vivo con más HP actual. Cada Guardián diferente que quite HP al jefe con Attack reduce el bono de carga en 20 puntos porcentuales.'],
      ['<strong>Round 3:</strong> prepare the marked Guardian’s protection before the announced breath resolves. A teammate can target them with a suitable consumable and still submit a main action. Three contributions reduce the bonus from +80% to +20%; they do not cancel the attack.','<strong>Ronda 3:</strong> prepara la protección del marcado antes de que se resuelva el aliento anunciado. Un compañero puede dirigirle un consumible apropiado y enviar además su acción principal. Tres aportes bajan el bono de +80% a +20%; no cancelan el ataque.']
    ])}${A('raids','See Vareth’s full phase guide','Ver la guía completa de las fases de Vareth','raid-vareth')}</details>
  </section>`;}
  prepend('combat-guide',()=>`<nav class="update-jumps" aria-label="${L('New combat lessons','Nuevas lecciones de combate')}"><a href="#combat-teamplay">${L('Consumables & allies','Consumibles y aliados')}</a><a href="#combat-worked-turns">${L('Worked turns','Turnos explicados')}</a>${A('mastery','Mastery trees','Árboles de maestría')}</nav>`);
  append('combat-guide',()=>support()+examples());
  append('consumables',()=>support('consumables-teamplay'));

  const names={lancer:['Lancer','Lancero'],explorer:['Explorer','Exploradora'],duelist:['Duelist','Duelista'],sentinel:['Sentinel','Centinela'],vanguard:['Vanguard','Vanguardia'],arcanist:['Arcanist','Arcanista'],pugilist:['Pugilist','Pugilista'],tracker:['Tracker','Rastreadora'],custodian:['Custodian','Custodio'],wanderer:['Wanderer','Errante'],alchemist:['Alchemist','Alquimista'],jadewind:['Jadewind','Jadewind']};
  const loops={
    lancer:['Hit early → store two charges → prepared attack.','Acierta pronto → guarda dos cargas → ataque preparado.'],
    explorer:['Complete Rest → prepare evasion → face the next hit.','Completa Rest → prepara evasión → afronta el siguiente golpe.'],
    duelist:['Keep attacking the same rival → build Pressure → strengthen later hits.','Sigue atacando al mismo rival → acumula Presión → potencia golpes posteriores.'],
    sentinel:['Fully block → store Firmness → cushion a guard break.','Bloquea por completo → guarda Firmeza → amortigua una ruptura.'],
    vanguard:['Check your HP → activate Overexertion → pay for a stronger attack.','Comprueba tu HP → activa Sobreesfuerzo → paga por un ataque más fuerte.'],
    arcanist:['Complete Rest → store Resonance → spend it with Focus.','Completa Rest → guarda Resonancia → gástala con Focus.'],
    pugilist:['Fully block → prepare Counterattack → attack next.','Bloquea por completo → prepara Contraataque → ataca después.'],
    tracker:['Hit to mark → follow that target → reduce its chance to dodge.','Acierta para marcar → persigue al objetivo → reduce su posibilidad de esquivar.'],
    custodian:['Choose Parry and an ally → share their final HP damage.','Elige Parry y un aliado → comparte su daño final de HP.'],
    wanderer:['Use Attack, Parry and Rest → complete a sequence → earn its finisher.','Usa Attack, Parry y Rest → completa la secuencia → recibe el efecto de cierre.'],
    alchemist:['Complete Rest → create a dose → prepare support next round.','Completa Rest → crea una dosis → prepara apoyo en la siguiente ronda.'],
    jadewind:['Stop damage with Parry → store Current → spend it on attacks or shields.','Detén daño con Parry → guarda Corriente → úsala en ataques o escudos.']
  };
  const masteryExamples={
    lancer:['At stage 1, two early successful hits build 2 charges; the next basic attack spends them.','En etapa 1, dos aciertos antes del rival reúnen 2 cargas; el siguiente ataque básico las gasta.'],
    explorer:['Stage 1: successful Rest in round 1 prepares +10 dodge points. If unused, they expire at the end of round 2. This is a chance, not a guaranteed dodge.','Etapa 1: un Rest exitoso en ronda 1 prepara +10 puntos de esquiva. Si no se usan, vencen al final de la ronda 2. Es una probabilidad, no una esquiva garantizada.'],
    duelist:['Stage 1: hit A, then hit A again. The second hit benefits from the first Pressure point. Attacking B resets the chain.','Etapa 1: acierta a A y vuelve a atacar a A. El segundo golpe aprovecha el primer punto de Presión. Atacar a B reinicia la cadena.'],
    sentinel:['Stage 1: fully block in two different rounds to store 2 Firmness. A later guard break can spend both to reduce overflow damage by 40.','Etapa 1: bloquea por completo en dos rondas distintas para guardar 2 Firmezas. Una ruptura posterior puede gastar ambas para reducir 40 del daño sobrante.'],
    vanguard:['With 200 maximum HP at stage 1, Overexertion costs 16 HP. You need more than 16 current HP; the payment still occurs if the empowered attack misses.','Con 200 de HP máximo en etapa 1, Sobreesfuerzo cuesta 16 HP. Necesitas más de 16 HP actual; pagas también si falla el ataque potenciado.'],
    arcanist:['Stage 1: successful Rest stores 2 Resonance. On an attack spending Focus with 100 base damage, Resonance adds 30 before defenses. Focus does not multiply that extra 30 again.','Etapa 1: un Rest exitoso guarda 2 Resonancias. En un ataque que gasta Focus con 100 de daño base, Resonancia añade 30 antes de defensas. Focus no vuelve a multiplicar esos 30.'],
    pugilist:['Stage 1: fully block, then Attack for the prepared +10%. Choosing Rest instead loses the preparation; preserving it through one Rest requires stage 3.','Etapa 1: bloquea por completo y después usa Attack para aprovechar el +10% preparado. Elegir Rest lo pierde; conservarlo durante un Rest requiere etapa 3.'],
    tracker:['Stage 1: hit A to create Trail. Your later attack against A faces 10 fewer dodge points. The first hit creating Trail does not receive that reduction.','Etapa 1: acierta a A para crear Rastro. Tu ataque posterior contra A enfrenta 10 puntos menos de esquiva. El primer golpe que crea Rastro todavía no recibe esa reducción.'],
    custodian:['Stage 1: if your protected ally would lose 100 HP after defenses, take 25 and they lose 75, while your round cap permits it. Your share can defeat you.','Etapa 1: si el aliado protegido perdería 100 HP después de defensas, recibes 25 y él pierde 75, mientras lo permita tu límite de ronda. Tu parte puede derribarte.'],
    wanderer:['Stage 1: complete Attack → Parry → Rest. The closing Rest adds 35 healing only if it succeeds. Repeating Attack before the sequence is complete resets it.','Etapa 1: completa Attack → Parry → Rest. El Rest de cierre añade 35 de cura solo si tiene éxito. Repetir Attack antes de completar la secuencia la reinicia.'],
    alchemist:['Stage 1: Rest successfully, then next round use the 40 HP dose on an ally and choose your main action too. Only 2 doses may be created in the whole fight.','Etapa 1: completa Rest; en la ronda siguiente usa la dosis de 40 HP en un aliado y elige también tu acción principal. Solo puedes crear 2 dosis en todo el combate.'],
    jadewind:['Parry must actually stop primary attack damage to generate Current. At stage 3, successful Rest can spend Current for a shield; interrupted Rest does neither.','Parry debe detener daño real de un ataque principal para generar Corriente. Desde etapa 3, un Rest exitoso puede gastar Corriente en un escudo; un Rest interrumpido no hace ninguna de las dos cosas.']
  };
  function masteryCard(id){const prices=id==='jadewind'?D.jadePrices:D.masteryPrices;return `<details class="fg-mastery" id="mastery-${id}"><summary><span><strong>${L(...names[id])}</strong><small>${L(...loops[id])}</small></span><span aria-hidden="true">＋</span></summary><div class="fg-mastery-body">
    ${['alchemist','arcanist','pugilist','tracker'].includes(id)?`<img class="fg-portrait" src="/assets/editorial/${id}.webp" width="240" height="240" alt="" loading="lazy">`:''}
    <p class="fg-example-note"><strong>${L('Try this sequence','Prueba esta secuencia')}:</strong> ${L(...masteryExamples[id])}</p>
    ${D.masteryTrees[id].map(([es,en],i)=>`<section class="fg-stage"><header><h3>${L('Stage','Etapa')} ${i+1}</h3><span>${i?number(prices[i])+' OIL':L('Included with unlock','Incluida al desbloquear')}</span></header><div class="${i>=4?'fg-branches':''}">${L(en,es).split('|').map(t=>`<p>${E(t)}</p>`).join('')}</div></section>`).join('')}
    <aside class="fg-rule"><h3>${L('Limits and equipment interactions','Límites e interacciones con el equipo')}</h3>${P(E(D.masteryRules[id][1]),E(D.masteryRules[id][0]))}</aside>
    ${id==='jadewind'?A('jadewind','Read the detailed Current guide','Lee la guía detallada de Corriente'):''}</div></details>`;}
  PAGES.mastery.h=()=>stamp()+P('Choose a character by the decisions you enjoy making. Open a card to compare all six stages and both branches. Each stage changes the previous values; percentages are not added together unless the rule says so.','Elige un personaje por las decisiones que te gusta tomar. Abre una ficha para comparar las seis etapas y sus dos ramas. Cada etapa modifica los valores anteriores; los porcentajes no se suman entre sí salvo que la regla lo indique.')+
    `<div class="fg-facts"><div><strong>11</strong><span>${L('starter characters','personajes iniciales')}</span></div><div><strong>6</strong><span>${L('stages per character','etapas por personaje')}</span></div><div><strong>A / B</strong><span>${L('permanent choice at stage 5','elección permanente en etapa 5')}</span></div></div>`+
    N('The Guardian is free. Your first starter is free once per account; additional starters cost <strong>45,000 OIL</strong>. Starter mastery upgrades total <strong>180,000 OIL</strong> each. Jadewind is separate: <strong>75,000 OIL</strong> to unlock and <strong>270,000 OIL</strong> in upgrades. Only your selected character’s mastery applies in supported battles.','El Guardián es gratuito. Tu primer inicial es gratis una vez por cuenta; cada inicial adicional cuesta <strong>45.000 OIL</strong>. Las mejoras de maestría suman <strong>180.000 OIL</strong> por inicial. Jadewind es especial: <strong>75.000 OIL</strong> al desbloquear y <strong>270.000 OIL</strong> en mejoras. En los combates compatibles se aplica la maestría del personaje seleccionado.')+
    `<nav class="update-jumps" aria-label="${L('Choose a mastery','Elegir una maestría')}">${Object.keys(names).map(id=>`<a href="#mastery-${id}" data-open-mastery="${id}">${L(...names[id])}</a>`).join('')}</nav>`+
    Object.keys(names).map(masteryCard).join('')+H('Balthier · in preparation','Balthier · en preparación')+P('Balthier’s mastery is not part of the released character roster. Its prediction mechanic is in development; this guide does not offer it as a purchasable or playable mastery.','La maestría de Balthier no forma parte del catálogo publicado de personajes. Su mecánica de predicción está en desarrollo; esta guía no la presenta como una maestría comprable o jugable.')+A('combat-guide','See the worked combat examples','Ver los ejemplos de combate','combat-worked-turns');

  const availability=f=>f[0].region==='harrowmere'?(D.harrowmerePrimordials.slice(2).includes(f.at(-1).id)?'procession':'vigil'):(f[0].expedition?'expedition':'mainland');
  const availabilityText=k=>L({vigil:'Vigil + Procession',procession:'Procession only',expedition:'Scheduled expedition',mainland:'Mainland · regional access'}[k],{vigil:'Vigilia + Procesión',procession:'Solo Procesión',expedition:'Expedición programada',mainland:'Continente · acceso regional'}[k]);
  function familyCard(f){const end=f.at(-1),av=availability(f);return `<article class="fg-species-card card" data-family="${E(f.map(s=>s.name).join(' ').toLowerCase())}" data-region="${E(end.region)}" data-availability="${av}">${end.region==='harrowmere'?img(end.id,end.name,'fg-creature'):`<img class="fg-creature" src="/assets/pokemax/${end.id}.webp" alt="${E(end.name)}" loading="lazy">`}<p class="ed-label">${E(regionName(end.region))}</p><h3>${E(end.emoji+' '+end.name)}</h3><p>${f.map(s=>E(s.name)).join(' → ')}</p><p class="fg-status">${availabilityText(av)}</p><p>${E(end.type)} · ${E(end.role)}</p><p class="card__st">HP / ATK / DEF / SPD: ${['hp','atk','def','spd'].map(k=>end.base[k]).join(' / ')}</p>${end.region==='harrowmere'?A('expeditions','Plan this expedition','Prepara esta expedición','harrowmere'):''}</article>`;}
  PAGES.species.d=`${Object.keys(D.species).length} ordinary Pokemax species in ${D.families.length} evolution families. Filter by region and encounter availability.`;
  TR_HEAD.species.d=`${Object.keys(D.species).length} especies comunes de Pokemax en ${D.families.length} familias evolutivas. Filtra por región y disponibilidad.`;
  PAGES.species.h=()=>stamp()+P(`Explore <strong>${Object.keys(D.species).length} ordinary species in ${D.families.length} three-stage families</strong>. Harrowmere adds four families. Hidden and unique discoveries are excluded; Primordial is an awakening of an existing species, not another species.`,`Explora <strong>${Object.keys(D.species).length} especies comunes en ${D.families.length} familias de tres etapas</strong>. Harrowmere añade cuatro familias. Se excluyen los descubrimientos ocultos y únicos; Primordial es el despertar de una especie existente, no otra especie.`)+P('Evolution thresholds are levels 16 and 36. The normal cap is 50; a supported Primordial can train to 60 after awakening. The numbers below are base stats, not a trained partner’s final stats.','Los umbrales de evolución son los niveles 16 y 36. El límite normal es 50; un Primordial compatible puede entrenar hasta 60 tras despertar. Los números de abajo son estadísticas base, no las estadísticas finales de un compañero entrenado.')+
    `<div class="fg-catalog"><div class="fg-filters"><label>${L('Find a species','Buscar una especie')}<input type="search" data-species-query placeholder="${L('Name of any evolution…','Nombre de cualquier evolución…')}"></label><label>${L('Region','Región')}<select data-species-region><option value="">${L('All regions','Todas las regiones')}</option>${[...new Set(D.families.map(f=>f[0].region))].sort().map(id=>`<option value="${id}">${E(regionName(id))}</option>`).join('')}</select></label><label>${L('Availability','Disponibilidad')}<select data-species-availability><option value="">${L('Any availability','Cualquier disponibilidad')}</option>${['mainland','expedition','vigil','procession'].map(k=>`<option value="${k}">${availabilityText(k)}</option>`).join('')}</select></label></div><p class="fg-filter-result" role="status" aria-live="polite">${D.families.length} ${L('families','familias')}</p><div class="fg-species-grid">${D.families.map(familyCard).join('')}</div></div>`+
    N('Expedition access follows the current departure schedule. During Harrowmere’s Procession the two Vigil families remain in the encounter pool; the two Procession families are added. Merchant Crossroads uses encounters from Starter Ruins, Crimson Plain and Stormbay Docks.','El acceso a expediciones sigue el calendario actual de salidas. Durante la Procesión de Harrowmere, las dos familias de Vigilia permanecen en los encuentros y se añaden las dos de Procesión. Merchant Crossroads usa encuentros de Starter Ruins, Crimson Plain y Stormbay Docks.')+`<div class="ed-guide-links">${A('lab','Calculate stats and moves','Calcula estadísticas y movimientos')}${A('primordial','Awakening and passives','Despertar y pasivas')}</div>`;
  const oldPets=PAGES.pets.h;PAGES.pets.h=()=>oldPets().replace(/<p class="b">(?:You catch them wild|Los capturas salvajes)[\s\S]*?<\/p>/,P(`The current ordinary catalog has <strong>${Object.keys(D.species).length} species in ${D.families.length} families</strong>, across mainland Valestia and four expedition destinations. Every family has three stages. Availability follows your region and the expedition’s phase.`,`El catálogo común actual tiene <strong>${Object.keys(D.species).length} especies en ${D.families.length} familias</strong>, entre Valestia continental y cuatro destinos de expedición. Cada familia tiene tres etapas. La disponibilidad depende de tu región y de la fase de la expedición.`));

  function harrowmereGear(id="harrowmere-equipment"){return `<section class="fg-section" id="${id}">${H('Harrowmere equipment: what changes in combat?','Equipo de Harrowmere: ¿qué cambia en combate?')}<div class="fg-two"><article class="fg-item">${img('last-vigil-lantern','Last Vigil Lantern')}<h3>Last Vigil Lantern</h3>${P('A gear with <strong>1 candle per fight; 2 at +5</strong>. A candle protects one interrupted Rest: all incoming hits during that Rest deal 20% less damage after the Rest penalty. You still lose the Rest healing, but prepare Focus if you survive. A safe Rest does not consume a candle.','Un gear con <strong>1 vela por combate; 2 a +5</strong>. Una vela protege un Rest interrumpido: todos los golpes recibidos durante ese descanso infligen 20% menos de daño después del castigo de Rest. Pierdes la cura del descanso, pero preparas Focus si sobrevives. Un descanso seguro no gasta una vela.')}${P('For a hit already calculated as 150 after the Rest penalty, the lantern’s 20% reduction makes it 120 at that step. It does not erase the original penalty or guarantee survival.','Para un golpe ya calculado como 150 después del castigo de Rest, la reducción del 20% del farol lo deja en 120 en ese paso. No elimina el castigo original ni garantiza sobrevivir.')}</article><article class="fg-item">${img('tithe-scythe','Tithe Scythe')}<h3>Tithe Scythe</h3>${P('Its active is used <strong>once per combat</strong>. A successful hit that removes HP applies Widow’s Tithe for the target’s next two complete turns: −15% STR/AGI/CON and −50% healing. At +5: −20% stats and −75% healing. Current and maximum HP are not recalculated by the curse.','Su activa se usa <strong>una vez por combate</strong>. Un golpe acertado que quite HP aplica Widow’s Tithe durante los próximos dos turnos completos del objetivo: −15% STR/AGI/CON y −50% de curación. A +5: −20% de atributos y −75% de curación. La maldición no recalcula el HP actual ni el máximo.')}${P('Choose the weapon skill as your main action. A dodge or a completely blocked hit does not apply the curse.','Elige la habilidad del arma como acción principal. Una esquiva o un golpe completamente bloqueado no aplica la maldición.')}</article></div>${H('Last Light equipment set','Conjunto de equipo Last Light')}${P(E(D.sets.last_light.summary),E(D.sets.last_light.summary_es))}${P('Equip both Tithe Scythe and Last Vigil Lantern to activate this set. Its shield is separate from the title named The Last Light.','Equipa Tithe Scythe y Last Vigil Lantern para activar este conjunto. Su escudo es independiente del t\u00edtulo llamado The Last Light.')}${A('expeditions','Shop and permanent workshop','Tienda y taller permanente','harrowmere-shop')}</section>`;}
  function harrowmere(){return `<section class="fg-section" id="harrowmere"><figure class="fg-landscape">${img('harrowmere-vigil',L('Lanterns along the misty road into Harrowmere','Faroles junto al camino entre niebla hacia Harrowmere'))}<figcaption><span>HARROWMERE</span><strong>${L('Keep the last lights burning.','Mantén encendidas las últimas luces.')}</strong></figcaption></figure>${stamp()}${P('A vanished harvest village returns through the fog. Harrowmere is a scheduled expedition from <strong>Ravennor</strong>, with its own story, hunts, Pokemax, Trial and exchange. Check the departure panel for the current opening and closing times.','Una aldea de cosecha desaparecida regresa entre la niebla. Harrowmere es una expedición programada desde <strong>Ravennor</strong>, con historia, cacerías, Pokemax, prueba y canje propios. Consulta en el panel de salidas las fechas actuales de apertura y cierre.')}
    <nav class="update-jumps" aria-label="${L('Harrowmere guide','Guía de Harrowmere')}"><a href="#harrowmere-phases">${L('Phases','Fases')}</a><a href="#harrowmere-activities">${L('Activities','Actividades')}</a><a href="#harrowmere-shop">${L('Exchange & workshop','Canje y taller')}</a><a href="#expedition-equipment">${L('Equipment','Equipo')}</a></nav>
    ${H('Travel and return','Viaje y regreso')}${P('Complete the expedition departure from Ravennor. The journey takes <strong>45 minutes each way</strong>. Being listed on the atlas does not mean departures are open. At closing, new hunts, Safari and Trials stop; battles already started can finish. Landed visitors have a <strong>six-hour departure window</strong> with exchange access before automatic return begins.','Completa la salida de expedición desde Ravennor. El trayecto tarda <strong>45 minutos en cada sentido</strong>. Aparecer en el atlas no significa que las salidas estén abiertas. Al cierre dejan de iniciarse cacerías, Safari y pruebas; los combates ya iniciados pueden terminar. Los visitantes que hayan llegado tienen <strong>seis horas de salida</strong> con acceso al canje antes del regreso automático.')}
    <section id="harrowmere-phases">${H('One village, two phases','Una aldea, dos fases')}<div class="fg-two"><article class="fg-phase">${img('harrowmere-vigil',L('Harrowmere during the Vigil','Harrowmere durante la Vigilia'))}<h3>The Vigil · ${L('Vigil','Vigilia')}</h3>${P('The base encounter pool contains Wicklet → Gourdling → Hollowgourd and Strawchick → Rookstitch → Gallowsrook.','Los encuentros base incluyen Wicklet → Gourdling → Hollowgourd y Strawchick → Rookstitch → Gallowsrook.')}</article><article class="fg-phase">${img('harrowmere-procession',L('Harrowmere during the Procession','Harrowmere durante la Procesión'))}<h3>The Procession · ${L('Procession','Procesión')}</h3>${P('Adds Cinderpup → Ashmaw → Pyrehound and Glimfawn → Veilhart → Wickerhart. The Vigil families remain available. Harrowglass OILballs have ×3.5 capture power here; otherwise they use basic power.','Añade Cinderpup → Ashmaw → Pyrehound y Glimfawn → Veilhart → Wickerhart. Las familias de Vigilia siguen disponibles. Las Harrowglass OILballs tienen potencia de captura ×3,5 aquí; fuera de esta condición usan potencia básica.')}</article></div>${P('Phases alternate every <strong>5 hours</strong> from the expedition’s start. A battle keeps the phase in which it began. In Procession hunts, the enemy starts with a total STR + AGI + CON equal to 120% of your initial effective total, rounded up and distributed by its role. HP follows its CON. Later buffs or curses do not rescale that enemy.','Las fases alternan cada <strong>5 horas</strong> desde el inicio de la expedición. Un combate conserva la fase en la que empezó. En las cacerías de Procesión, el enemigo comienza con una suma de STR + AGI + CON equivalente al 120% de tu total efectivo inicial, redondeado hacia arriba y repartido según su rol. Su HP sigue su CON. Los bonos o maldiciones posteriores no vuelven a ajustar al enemigo.')}</section>
    <section id="harrowmere-activities">${H('What to do after arriving','Qué hacer al llegar')}${steps([
      ['<strong>Explore and hunt.</strong> Earn Harrow Obols through successful regional hunts; normal energy, XP and OIL rules still apply.','<strong>Explora y caza.</strong> Obtén Harrow Obols al ganar cacerías regionales; se mantienen las reglas normales de energía, XP y OIL.'],
      ['<strong>Play the three story chapters.</strong> These are three-player adventures. Use the expedition’s story panel and its current entry requirements.','<strong>Juega los tres capítulos de historia.</strong> Son aventuras para tres jugadores. Usa el panel de historia de la expedición y consulta sus requisitos actuales.'],
      ['<strong>Build your Pokemax party.</strong> Explore Safari and face Bellkeeper Elowen in the Bellkeeper’s Trial. Her team includes Hollowgourd, Gallowsrook and Wickerhart; the special Trial discovery is separate from the 141-species ordinary catalog.','<strong>Prepara tu equipo Pokemax.</strong> Explora Safari y enfrenta a Bellkeeper Elowen en la prueba del campanero. Su equipo incluye Hollowgourd, Gallowsrook y Wickerhart; el descubrimiento especial de la prueba se cuenta aparte del catálogo de 141 especies comunes.']
    ])}<div class="fg-species-grid">${D.families.filter(f=>f[0].region==='harrowmere').map(familyCard).join('')}</div>${A('primordial','See the four Harrowmere Primordial passives','Consulta las cuatro pasivas Primordiales de Harrowmere')}</section>
    <section id="harrowmere-shop">${H('Spend Obols and keep your equipment growing','Usa tus óbolos y sigue mejorando tu equipo')}${table(L(['Exchange item','Harrow Obols','Purchase limit'],['Objeto del canje','Harrow Obols','Límite de compra']),[
      ['Regen Potion',5,'—'],['Vigil Ward (Protective Shield Potion)',10,'—'],['1,000 OIL',8,'—'],['Harrowglass OILball',6,5],['Veil Wax / Bell Iron',3,L('5 each','5 de cada uno')],['Last Light Insignia',15,1],['Last Vigil Lantern',45,1],['Tithe Scythe',65,1],['Chainers Promo Code',60,L('1 · shared stock','1 · stock compartido')]
    ])}${P('The exchange checks your purchases and available stock. Last Light Insignia permanently unlocks <strong>The Last Light</strong>: +1 AGI while equipped and +1 Obol per successful Harrowmere hunt. It is a title reward, separate from competitive badges.','El canje comprueba tus compras y las existencias disponibles. Last Light Insignia desbloquea permanentemente <strong>The Last Light</strong>: +1 AGI mientras esté equipado y +1 óbolo por cacería ganada en Harrowmere. Es un premio de título, separado de los badges competitivos.')}${P('Owners can keep making their equipment’s enhancement material in the <strong>permanent workshop after the expedition closes</strong>. Owning the lantern enables Veil Wax; owning the scythe enables Bell Iron. The workshop does not grant the original equipment.','Los propietarios pueden seguir fabricando el material de mejora de su equipo en el <strong>taller permanente después del cierre</strong>. Poseer el farol habilita Veil Wax; poseer la guadaña habilita Bell Iron. El taller no entrega el equipo original.')}${table(L(['Material','Workshop cost'],['Material','Costo en el taller']),[['Veil Wax','1,500 OIL · 2 Copper Ore · 2 Linen Fiber · 1 Medic Resin'],['Bell Iron','2,000 OIL · 2 Honed Scrap · 2 Forged Alloy Band · 1 Kinetic Core']])}</section>${harrowmereGear("expedition-equipment")}${A('valestia','Return to the atlas','Volver al atlas')}</section>`;}
  prepend('expeditions',()=>N('Four destinations are documented: Sunken Fang, Hollowstar Crater, Nyxhaven and <a href="#harrowmere">Harrowmere</a>. Their departure schedules and currencies are separate.','Hay cuatro destinos documentados: Sunken Fang, Hollowstar Crater, Nyxhaven y <a href="#harrowmere">Harrowmere</a>. Sus calendarios de salida y monedas son independientes.'));
  const oldExpeditions=PAGES.expeditions.h;PAGES.expeditions.h=()=>oldExpeditions().replace(/Three are open now/g,'Other destination guides').replace(/Tres est\u00e1n abiertos ahora/g,'Otras gu\u00edas de destino');
  append('expeditions',harrowmere);
  append('gear',harrowmereGear);
  append('weapons',()=>H('Tithe Scythe and its two-turn curse','Tithe Scythe y su maldición de dos turnos')+P('Harrowmere’s scythe adds an active strike that curses a target only if it removes HP. Read the equipment guide for the duration, enhancement effects and workshop.','La guadaña de Harrowmere añade un golpe activo que maldice al objetivo solo si le quita HP. Consulta la guía de equipo para conocer la duración, mejoras y taller.')+A('gear','Understand the scythe and lantern','Entender la guadaña y el farol','harrowmere-equipment'));

  function severin(){return `<section id="raid-severin" class="raid-boss fg-section"><figure class="fg-landscape">${img('severin-arena-1',L('The Lantern Causeway in Harrowmere','The Lantern Causeway en Harrowmere'))}<figcaption><span>HARROWMERE · THE LANTERN CAUSEWAY</span><strong>Severin — The Pale Huntsman</strong></figcaption></figure><div class="raid-copy">${stamp(true)}${N('<strong>Encounter preview.</strong> The encounter design is documented here, but its balance is still provisional. This page does not announce a live raid, final difficulty stats or rewards. Check the published raid panel.','<strong>Avance del encuentro.</strong> Esta guía explica el diseño actual del encuentro; su balance todavía es provisional. Esta página no anuncia una raid abierta, estadísticas definitivas ni recompensas. Consulta el panel de raids publicado.')}
    <div class="fg-two"><figure class="fg-boss-portrait">${img('severin-1','Severin — The Last Hunter')}<figcaption>I · The Last Hunter</figcaption></figure><figure class="fg-boss-portrait">${img('severin-2','Severin — The Pale Procession')}<figcaption>II · The Pale Procession</figcaption></figure></div>
    ${H('Two lives. One marked target.','Dos vidas. Un objetivo marcado.')}${P('The first life is The Last Hunter; defeating it begins The Pale Procession with its own HP pool. In phase II, Hunter’s Verdict adds an extra shot every three rounds. Read the warning and countdown on the battle panel.','La primera vida es The Last Hunter; al derrotarla empieza The Pale Procession con su propia reserva de HP. En fase II, Hunter’s Verdict añade un disparo extra cada tres rondas. Lee el aviso y la cuenta del panel de combate.')}${steps([
      ['<strong>Warning:</strong> one round before the shot, Severin marks the living Guardian with the most current HP. It is current HP, not maximum HP.','<strong>Aviso:</strong> una ronda antes del disparo, Severin marca al Guardián vivo con más HP actual. Cuenta el HP actual, no el máximo.'],
      ['<strong>Prepare:</strong> coordinate protection and recovery for that Guardian. The mark stays on the announced target; it does not jump to a teammate because HP rankings change.','<strong>Preparación:</strong> coordinen protección y recuperación para ese Guardián. La marca permanece en el objetivo anunciado; no salta a otro compañero porque cambie el orden de HP.'],
      ['<strong>Shot:</strong> the extra attack uses 200% of normal attack damage before defenses, without Focus, Ultra Focus or critical multipliers. If the marked target becomes invalid, the shot cancels instead of silently retargeting.','<strong>Disparo:</strong> el ataque extra usa 200% del daño de un ataque normal antes de defensas, sin multiplicadores de Focus, Ultra Focus ni crítico. Si el marcado deja de ser un objetivo válido, el disparo se cancela en vez de cambiar de destinatario sin avisar.'],
      ['<strong>Following round:</strong> if the shot removes HP and the Guardian survives, Hunter’s Curse halves STR, AGI and CON for that next round. Current and maximum HP do not change. Do not plan your next attack as if your attributes were untouched.','<strong>Ronda siguiente:</strong> si el disparo quita HP y el Guardián sobrevive, Hunter’s Curse reduce a la mitad STR, AGI y CON durante esa siguiente ronda. El HP actual y máximo no cambian. No calcules tu próximo ataque como si tus atributos siguieran intactos.']
    ])}<figure class="fg-landscape">${img('severin-arena-2',L('The Procession crosses Severin’s arena','La Procesión cruza el escenario de Severin'))}</figure>${A('expeditions','Explore Harrowmere','Explorar Harrowmere','harrowmere')}</div></section>`;}
  prepend('raids',()=>N('New: <a href="#raid-severin">Severin’s illustrated encounter preview</a>. His release status is shown separately from the established boss guides.','Nuevo: <a href="#raid-severin">avance ilustrado del encuentro de Severin</a>. Su estado de publicación se distingue de las guías de los jefes establecidos.'));
  append('raids',severin);

  const badgeSpanish={global_level:'Alcanza el mayor nivel global; la XP desempata.',oil_balance:'Mantén el mayor saldo actual de OIL.',boss_clears:'Acumula más victorias contra jefes.',daily_global_xp_utc:'Obtén más XP global durante el día UTC actual.',community_messages:'Acumula más mensajes comunitarios válidos.',lootdrop_wins_lifetime:'Acumula más victorias de Loot Drop.',doppeldrop_wins_lifetime:'Acumula más victorias de Doppel Drop.',blinddrop_wins_lifetime:'Acumula más victorias de Blind Drop.',tagdrop_wins_lifetime:'Acumula más victorias de Tag Drop.',triad_wins_lifetime:'Acumula más victorias de Triad Drop.',escort_wins_lifetime:'Acumula más victorias de Escort Drop.',horde_wins_lifetime:'Acumula más victorias de Horde.',horde_damage_lifetime:'Acumula más daño en Horde.',mission_wins_lifetime:'Acumula más victorias en modo Mission.',oil_spent_lifetime:'Acumula más OIL gastado.',clan_oil_contributed_lifetime:'Acumula más OIL aportado al tesoro del clan.',total_damage_lifetime:'Acumula más daño total de combate.',total_healing_lifetime:'Acumula más HP recuperado por cualquier fuente.',potions_used_lifetime:'Usa más pociones en combate.',parry_damage_lifetime:'Acumula más daño mediante contraataques de Parry.',crit_hits_lifetime:'Acumula más golpes críticos.',dodges_lifetime:'Acumula más esquivas.',attacks_dodged_against_lifetime:'Acumula más ataques propios esquivados por otros jugadores.',roulette_spins_lifetime:'Realiza más giros de Salvage Vault.',raid_mentor_first_clears:'Ayuda a otros a conseguir primeras victorias en dificultades de raid que ya superaste.',daily_full_completion_days:'Completa las tres misiones diarias en más días UTC distintos.',survival_qualifier_waves:'Supera más oleadas en una sola partida de Survival Qualifier.',survival_classic_score:'Consigue la mayor puntuación de Classic Survival entre jugadores elegibles.',survival_qualifier_score:'Consigue la mayor puntuación de Qualifier Survival entre jugadores elegibles.',liberator_medals:'Reúne más medallas de liberación; desempata el ID de jugador menor.',story_scenes_completed:'Completa más escenas de historia distintas; repetirlas no suma.',expedition_currency_lifetime:'Acumula más monedas de expedición obtenidas: cada moneda vale un punto, incluidas las gastadas.',gym_defenses_lifetime:'Acumula más defensas válidas de gimnasio Pokemax; no cuentan AFK ni repeticiones bloqueadas.',battle_royale_wins:'Gana más eventos completos de Battle Royale.',arsenal_items_owned:'Posee más armas y gears: las copias cuentan y el equipo equipado no se duplica.',character_mastery_total:'Suma más etapas de maestría entre personajes desbloqueados; tres en etapa 6 suman 18.',codex_entries_count:'Descubre más entradas diferentes del Códice.'};
  function bonus(b){const labels={str:'STR',agi:'AGI',con:'CON',hp:'HP',parry_def:'Parry DEF',crit_chance_pct:L('critical points','puntos de crítico'),dodge_chance_pct:L('dodge points','puntos de esquiva')};const values={[b.bonus_kind]:b.bonus_value};Object.keys(labels).forEach(k=>{if(b['bonus_extra_'+k])values[k]=(values[k]||0)+b['bonus_extra_'+k];});return Object.entries(values).map(([k,v])=>`+${v} ${labels[k]||k}`).join(' · ');}
  PAGES.badges={t:'Competitive badges',e:'Your place in Valestia',d:`All ${D.badges.length} competitive badges: criteria, bonuses, eligibility and preferences.`,h:()=>stamp()+`<div class="fg-facts"><div><strong>${D.badges.length}</strong><span>${L('badge categories','categorías de insignias')}</span></div><div><strong>1</strong><span>${L('owner per badge','propietario por insignia')}</span></div><div><strong>1</strong><span>${L('badge per player','insignia por jugador')}</span></div></div>`+P('Badges are competitive distinctions. Leading a metric does not permanently unlock a collectible for everyone: ownership is reassigned according to eligible rankings and player preferences. Their bonuses apply while you hold the badge.','Los badges son distinciones competitivas. Liderar una métrica no desbloquea un coleccionable permanente para todos: la propiedad se reasigna según las clasificaciones elegibles y las preferencias de los jugadores. Sus bonos se aplican mientras conservas la insignia.')+
    H('Eligibility and choosing a preference','Requisitos y elección de preferencia')+P(`Regular candidates need a positive score and at least one Guardians combat in the last <strong>${D.badgeActivityDays} days</strong>. The activity window does not reset lifetime metrics. Story accounts do not compete. If the game offers several eligible choices, select a preference; a successful change locks that preference for <strong>${D.badgeChoiceDays} days</strong>. This cooldown does not guarantee ownership for three days.`,`Los candidatos normales necesitan una puntuación positiva y al menos un combate de Guardians en los últimos <strong>${D.badgeActivityDays} días</strong>. Esa ventana de actividad no reinicia las métricas acumuladas. Las cuentas de historia no compiten. Si el juego ofrece varias opciones elegibles, elige una preferencia; un cambio válido bloquea esa preferencia durante <strong>${D.badgeChoiceDays} días</strong>. Ese plazo no garantiza conservar la insignia durante tres días.`)+
    N('You still need to qualify for the selected badge. Apex Vanguard only belongs to the highest-ranked eligible player; if that player obtains a preferred different badge, Apex can remain vacant. Check the game for current owners and available choices.','Debes seguir cumpliendo los requisitos de la insignia elegida. Apex Vanguard solo corresponde al jugador elegible de mayor rango; si este obtiene otra insignia preferida, Apex puede quedar vacante. Consulta en el juego los propietarios actuales y tus opciones disponibles.')+
    `<div class="fg-badge-grid">${D.badges.map(b=>`<article class="fg-badge"><span class="fg-badge-icon" aria-hidden="true">${E(b.emoji)}</span><h2>${E(b.badge_name)}</h2><p class="fg-badge-title">${E(b.title)}</p><p>${E(L(D.badgeCriteria[b.metric_key],badgeSpanish[b.metric_key]))}</p><strong>${bonus(b)}</strong></article>`).join('')}</div>`};
  TR_HEAD.badges={t:'Badges competitivos',e:'Tu lugar en Valestia',d:`Las ${D.badges.length} insignias competitivas: criterios, bonificaciones, requisitos y preferencias.`};
  NAV.find(g=>g[1].some(i=>i[0]==='mastery'))[1].push(['badges','Competitive badges','Badges competitivos']);
  prepend('economy',()=>N('Badges are competitive distinctions with limited ownership. '+A('badges','Read all criteria and bonuses',''),'Los badges son distinciones competitivas con propietarios limitados. '+A('badges','','Consulta todos los criterios y bonos')));
  // Replace the earlier generic achievement description rather than leaving contradictory rules below.
  const oldEconomy=PAGES.economy.h;PAGES.economy.h=()=>oldEconomy().replace(/Achievements for hitting milestones[^<]*/g,L('Competitive distinctions assigned by ranking and eligibility. See the badge catalog.','Distinciones competitivas asignadas por clasificación y requisitos. Consulta el catálogo de badges.')).replace(/Logros por alcanzar hitos[^<]*/g,'Distinciones competitivas asignadas por clasificación y requisitos. Consulta el catálogo de badges.');

  function portalLesson(){return `<section id="portal-pokemax" class="fg-section">${H('Pokemax: from Discord to your browser','Pokemax: de Discord al navegador')}${stamp()}${steps([
    ['<strong>Start in Discord.</strong> For Safari, use <code>!safari</code> in your current region’s channel. Other battles keep their normal entry panels and requirements.','<strong>Empieza en Discord.</strong> Para Safari, usa <code>!safari</code> en el canal de tu región actual. Los otros combates conservan sus paneles de entrada y requisitos.'],
    ['<strong>Open “Play on Web”.</strong> Use the battle’s button and sign in with the same Discord account. Only participants can control their own team.','<strong>Abre «Jugar en la web».</strong> Usa el botón del combate e inicia sesión con la misma cuenta de Discord. Solo los participantes pueden controlar su propio equipo.'],
    ['<strong>Choose a move or switch.</strong> Captures and fleeing appear when the encounter allows them. A confirmed choice also locks that turn’s choice in the other interface; it does not grant another turn. Gene scanning remains in Discord.','<strong>Elige un movimiento o cambio.</strong> Capturar y huir aparecen cuando el encuentro lo permite. Una elección confirmada bloquea también la decisión de ese turno en la otra interfaz; no concede otro turno. El escaneo de genes sigue en Discord.'],
    ['<strong>Resume your active battle.</strong> Use the portal’s Pokemax Center or reopen your battle link. The center resumes existing battles; it is not a new opponent search. Animation playback does not pause the turn timer.','<strong>Retoma tu combate activo.</strong> Usa el Centro Pokemax del portal o vuelve a abrir tu enlace. El centro retoma combates existentes; no es un buscador nuevo de rivales. Las animaciones no pausan el tiempo del turno.']
  ])}${table(L(['Experience','Account progress','Where to begin'],['Experiencia','Progreso de cuenta','Dónde empezar']),[
    [L('Public demo','Demo pública'),L('No real inventory, OIL or saved RPG rewards','Sin inventario real, OIL ni premios guardados del RPG'),A('play','Try the demo','Probar la demo')],
    [L('Account practices','Prácticas con cuenta'),L('1v1 / 2v2; PvE or PvP. OIL rewards depend on enabled rules and daily limits.','1v1 / 2v2; PvE o PvP. Los premios de OIL dependen de las reglas habilitadas y límites diarios.'),L('Available practice lobby','Sala de práctica disponible')],
    [L('Connected story','Historia conectada'),L('Chapter I, missions 1–14. Shared first-clear progress with Discord; replays do not pay twice.','Capítulo I, misiones 1–14. Primera victoria compartida con Discord; repetir no paga dos veces.'),L('Adventures → Story','Aventuras → Historia')],
    [L('Real Pokemax battle','Combate Pokemax real'),L('Uses the same battle, party and eligible rewards as Discord. Real captures can spend OILballs.','Usa el mismo combate, equipo y premios elegibles que Discord. Las capturas reales pueden gastar OILballs.'),L('Discord → Play on Web','Discord → Jugar en la web')]
  ])}${P('If the web battle button is unavailable, continue through Discord. The feature must be enabled in the running game, and you must be a participant. Side Stories in the portal summarizes Discord progress; it does not make every side quest playable in the browser.','Si el botón de combate web no está disponible, continúa desde Discord. La función debe estar habilitada en el juego y debes ser participante. Historias secundarias en el portal resume el progreso de Discord; no convierte todas las misiones secundarias en aventuras jugables en el navegador.')}</section>`;}
  prepend('player-portal',()=>`<nav class="update-jumps"><a href="#portal-pokemax">${L('Play Pokemax on the web','Jugar Pokemax en la web')}</a>${A('badges','Badges and preferences','Badges y preferencias')}</nav>`);
  append('player-portal',portalLesson);
  append('petbattle',()=>A('player-portal','Continue this battle in your browser','Continúa este combate en el navegador','portal-pokemax'));
  prepend('changelog',()=>`<section class="ed-update"><time datetime="2026-11-09">09 NOV 2026</time>${H('A field guide for your next adventure','Una guía para tu próxima aventura')}${P('Expanded combat lessons, all released mastery trees, Harrowmere’s expedition, the updated Pokemax catalog, competitive badges and connected web play. Severin is presented as a provisional encounter preview.','Lecciones de combate ampliadas, todos los árboles de maestrías publicados, expedición de Harrowmere, catálogo Pokemax actualizado, badges competitivos y juego web conectado. Severin se presenta como un avance provisional del encuentro.')}<div class="update-cards">${[['combat-guide','Learn your next move','Entiende tu próxima acción'],['mastery','Compare every mastery','Compara cada maestría'],['expeditions','Discover Harrowmere','Descubre Harrowmere','harrowmere'],['species','Explore 141 species','Explora 141 especies'],['badges','Find your distinction','Encuentra tu distinción'],['raids','Severin · preview','Severin · avance','raid-severin']].map(([id,en,es,anchor])=>`<article><h3>${A(id,en,es,anchor)}</h3></article>`).join('')}</div></section>`);
  const oldHome=PAGES.home.h;PAGES.home.h=()=>oldHome().replace(/<section class="ed-section ed-journal">[\s\S]*?<\/section>/,`<section class="ed-section ed-journal"><div><p class="ed-label">09 NOV 2026</p><h2>${L('Know your next move.','Entiende tu próxima jugada.')}</h2>${A('changelog','Read the new field guide','Conoce las nuevas guías')}</div><a class="ed-link" href="${U('expeditions','harrowmere')}">${img('harrowmere-vigil','','journal-image')}<h3>Harrowmere</h3><p>${L('Vigil, Procession and the road of lanterns.','Vigilia, Procesión y el camino de los faroles.')}</p></a><a class="ed-link" href="${U('mastery')}"><h3>${L('Find your fighting style','Encuentra tu forma de luchar')}</h3><p>${L('Every stage, both branches and examples you can follow.','Cada etapa, ambas ramas y ejemplos que puedes seguir.')}</p></a></section>`);

  function filterCatalog(root){const q=root.querySelector('[data-species-query]').value.trim().toLowerCase(),r=root.querySelector('[data-species-region]').value,a=root.querySelector('[data-species-availability]').value;let count=0;root.querySelectorAll('[data-family]').forEach(card=>{card.hidden=!!((q&&!card.dataset.family.includes(q))||(r&&card.dataset.region!==r)||(a&&card.dataset.availability!==a));if(!card.hidden)count++;});root.querySelector('[role="status"]').textContent=count+' '+L('families match','familias coinciden');}
  document.addEventListener('input',ev=>{const root=ev.target.closest('.fg-catalog');if(root)filterCatalog(root);});
  document.addEventListener('change',ev=>{const root=ev.target.closest('.fg-catalog');if(root)filterCatalog(root);});
  document.addEventListener('click',ev=>{const link=ev.target.closest('[data-open-mastery]');if(link)document.getElementById('mastery-'+link.dataset.openMastery).open=true;});
  function openAnchor(){if(location.hash.startsWith('#mastery-')){const el=document.getElementById(location.hash.slice(1));if(el?.tagName==='DETAILS')el.open=true;}}
  window.addEventListener('hashchange',openAnchor);setTimeout(openAnchor,0);
};
